// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // Fuzz parameters:
    // - bool shouldFail: whether the callee reverts (we deploy a helper that can be toggled)
    // - address fromAddr: arbitrary actor passed as `from` into transfer
    // - uint256 v: arbitrary uint value passed through
    // - uint256 tosCount: number of recipients; we will bound it to 1..4 to keep helper behaviour simple
    function testFuzz_property(bool shouldFail, address fromAddr, uint256 v, uint256 tosCount) public {
        // keep tosCount in a small but non-empty domain so the loop runs at least once
        uint256 n = bound(tosCount, 1, 4);

        // Deploy a recorder helper that exposes the target function transferFrom and can be toggled to revert.
        Recorder rec = new Recorder();
        rec.setShouldFail(shouldFail);

        // Build recipients array of length n; use distinct addresses derived from fromAddr and index
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            // Derive pseudo-random addresses using keccak so fuzzer can vary them
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(fromAddr, v, i)))));
        }

        // Call transfer and observe whether it completes (ok=true) or reverts (ok=false).
        bool ok;
        try c.transfer(fromAddr, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (observed via the public surface of the Recorder):
        // - When the Recorder is set to succeed (shouldFail==false), the callee's transferFrom implementations will succeed for each call => the reference contract completes successfully (ok==true).
        // - When the Recorder is set to revert (shouldFail==true), the external call fails => the reference contract reverts (ok==false).
        // We assert that ok equals !shouldFail (i.e. succeeds exactly when callee is not failing).
        // This holds for the reference C for all inputs; the mutant inverts the success check and will make this assertion fail for inputs where shouldFail is true/false accordingly.
        assertTrue(ok == (!shouldFail));
    }
}

// Recorder implements the exact function signature that C calls via abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), ...)
// It records that it was called and can be toggled to revert to exercise both success and failure outcomes.
contract Recorder {
    bool public shouldFail;
    uint256 public calls;
    // store last received args for visibility
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;

    function setShouldFail(bool s) external {
        shouldFail = s;
    }

    // Match signature: transferFrom(address from, address to, uint256 v)
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        if (shouldFail) {
            revert("Recorder forced revert");
        }
        return true;
    }
}
